import{_ as e,c as r,o as p,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"24、【复】 震下坤上","description":"周易尚氏学 - 24、【复】 震下坤上","frontmatter":{"title":"24、【复】 震下坤上","description":"周易尚氏学 - 24、【复】 震下坤上"},"headers":[],"relativePath":"zh/classics/shangshi/029.md","filePath":"zh/classics/shangshi/029.md"}'),h={name:"zh/classics/shangshi/029.md"};function s(t,a,l,n,c,d){return p(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_24、【复】-震下坤上" tabindex="-1">24、【复】 震下坤上 <a class="header-anchor" href="#_24、【复】-震下坤上" aria-label="Permalink to “24、【复】 震下坤上”">​</a></h1><p>阳反故曰复。出人反复。皆对姤言。复者姤之反。若舍股（左艮）不言。则复何所自乎。人者人巽。出者出震。坤为疾。象失传。详焦氏易诂阳通故无疾。阴以阳为朋。剥穷上反下故曰朋来。阳遇阴故无咎。阳自始而消。消至剥上。六日。反复则七日。自复而息。息至决（无左）上。六日。反姤仍七日。循环不已。故曰反复其道。七日来复。复阳长。故曰利有攸往。</p><p>彖曰。复亨。刚反。动而以顺行。是以出入无疾。朋来无咎。反复其道。七日来复。天行也。利有攸往。刚长也。复其见天地之心乎。</p><p>震动坤顺。故日动而以顺。天行。天道也。言阴阳刚柔往来消长。天道固如斯也。此天地之心也。坤为心。象失传。详鱼氏易诂此以爻数括天地间之公例公理。其谓卦气起中孚。至复为七日。不推于数不合。只六日七分且于理大谬。是皆执于自姤至复为七月。经言七日故疑也。岂知易辞皆举一例。包括万有。十日数至七必相反。辰数亦然即以日言。幽（内双豕）诗云一之日。二之日。日皆谓月。侯果已言之矣。阴阳相遇为朋。自此象失传。皆用卦变。俟阳息至二成兑。二阳为朋。虞氏之说讹误至今。又五行志。京房易传曰。复崩来无咎。读朋为崩。是用覆象。谓剥艮覆在下为山崩。而易林遇此象。亦往往曰山崩。京所受也。其详皆在焦氏易诂中。覆象久失传。后惟惠栋用此说。实易言覆象者。不止此也。</p><p>象曰。雷在地中。复。先王以至曰闭关。商旅不行。后不省方。</p><p>曰至日则兼二至言也。姤云。施命浩四方。即诰戒商旅将闭关也。易林晋之解。所谓二至之戒也。盖古最重二至。汉书薛宣传。日至休吏。所繇来久。后汉鲁恭传。易五月用事。先王施命令止四方行者。是夏至亦休息。与冬至同、坤为门户。故曰关。震为商旅。坤闭故曰闭关。曰不行。坤为方。震为王。</p><p>初九。不远复，无祗悔，元吉。</p><p>复在内。故曰不远复。严元照云。只从氏非。此当从氏。氏是同用。故王肃作提（左衣）。坎低既平。京房亦作提王陶庐云。唐石经即作祗。氏是古同部。故得同用。若氏（下、）则另为一部。不同部者不相假。古之例也。然则今作祗者误也，袄郑云病也。段玉裁云。郑盖借祗为氏（加　）。按祗之训病。诗小雅何人斯。壹者之来。俾我祗也。毛传祗病也。兹训为病。正本毛传。段谓借袄为氏（加　）非。病犹苗（中　）也。复出人无疾。故无苗（中　）悔。乾元通。故元吉。</p><h3 id="象曰。不远之复。以修身也。坤为身。阳微故宜修养以待。" tabindex="-1">象曰。不远之复。以修身也。坤为身。阳微故宜修养以待。 <a class="header-anchor" href="#象曰。不远之复。以修身也。坤为身。阳微故宜修养以待。" aria-label="Permalink to “象曰。不远之复。以修身也。坤为身。阳微故宜修养以待。”">​</a></h3><p>六二。休复。吉。</p><p>休者俟也。俟阳息至二故吉。</p><h3 id="象曰。休复之吉。以下仁也。" tabindex="-1">象曰。休复之吉。以下仁也。 <a class="header-anchor" href="#象曰。休复之吉。以下仁也。" aria-label="Permalink to “象曰。休复之吉。以下仁也。”">​</a></h3><p>仁者初也。阳主生故曰仁。以下仁者。言下阳即息至二。静俟则吉也。</p><p>六三。频复。厉。无咎。</p><p>虞翻曰。频蹙也。三失位。故频复。按频古文颦字。故云频蹙。三失位。承乘皆阴。又无应予。失类极</p><h3 id="象曰。频复之厉。义无咎也。" tabindex="-1">象曰。频复之厉。义无咎也。 <a class="header-anchor" href="#象曰。频复之厉。义无咎也。" aria-label="Permalink to “象曰。频复之厉。义无咎也。”">​</a></h3><p>六四。中行独复。</p><p>文言乾九四云。中不在人。中谓三四。居一卦之中也。又系辞云。其初难知。其上易知。若夫杂物撰德。非其中爻不备。中爻谓中四交。即下所谓二与四三与五也。四居卦中。独与初应。故曰中行独复。虞翻谓四不在二五。何得称中行。岂知三四称中爻。易固有明例也。</p><h3 id="象曰。中行独复。以从道也。" tabindex="-1">象曰。中行独复。以从道也。 <a class="header-anchor" href="#象曰。中行独复。以从道也。" aria-label="Permalink to “象曰。中行独复。以从道也。”">​</a></h3><p>道谓初。从道谓应初。</p><p>六五。敦复。无悔。</p><p>敦与屯通。诗大雅铺敦淮愤（左水）。笺敦当作屯。扬雄甘泉赋。敦万骑于中营兮。注敦与屯同。又按幽（双豕）风云。敦彼独宿。即屯彼独宿也。屯者止也。次也。而敦又与顿同。尔雅释丘。丘一成为敦丘。疏即卫风之顿丘。顿亦止也。史记王翦传三日三夜不顿舍。是也。是敦有止意待意。敦复者言五应在二。阳即升二。五稍待即有应也。故临上六亦曰敦临。以上六亦稍待。阳即息三。有应也。旧诂皆训为敦厚。非。</p><h3 id="象曰。敦复无悔。中以自者也。" tabindex="-1">象曰。敦复无悔。中以自者也。 <a class="header-anchor" href="#象曰。敦复无悔。中以自者也。" aria-label="Permalink to “象曰。敦复无悔。中以自者也。”">​</a></h3><p>向秀曰。考察也。五中位。应在二。亦中位。阳息即至二。五有应。故无侮。中以自考者。释敦之故。易之道贵将来。言顿止以待中二之阳息。自考省也。与临上之志在内义同。</p><p>上六。迷复。凶。有灾眚。用行师。终有大败。以其国君凶。至于十年不克征。</p><p>凡上六多不吉。上穷也。坤为迷为死丧。故有灾眚。坤为众故为师。坤为死丧。故行师终有大败。坤为国。震为君。象失传。详焦氏易诂故曰国君。坤为十年。震为征。不克征。言不能兴起也。比上六后夫凶。师上六小人勿用。皆以其不承阳也。他爻皆可承阳。独上六不能不承阳则背叛君命。而殃及国君。故曰以其为君凶。君者国之本。国君受协。根本动摇。故其凶至于十年也。</p><h3 id="象曰。迷复之凶。反君道也。" tabindex="-1">象曰。迷复之凶。反君道也。 <a class="header-anchor" href="#象曰。迷复之凶。反君道也。" aria-label="Permalink to “象曰。迷复之凶。反君道也。”">​</a></h3><p>反君道。即谓上六不承阳。旧解皆以不顺君命为反君道。然上六之何以独反君道。其故无能明者。此与六五敦复。及临之敦临义晦同也。</p>',28)])])}const m=e(h,[["render",s]]);export{_ as __pageData,m as default};
